#include <iostream>
#include <map>
using namespace std;

map<pair<int, int>, long long> all;
map<tuple<int, int, int>, long long> limit;
int n = 0, m = 0;

long long searchall(int start, int end) {
    if (start == end) {
        return 1;
    }
    pair<int, int> key = make_pair(start, end);
    if (all.find(key) != all.end()) {
        return all[key];
    }
    all[key] = 0;
    all[key] += searchall(start + 1, end);
    all[key] += searchall(start, end - 1);
    for (int i = start + 1; i < end; ++i) {
        all[key] += searchall(start, i - 1) * searchall(i + 1, end);
    }
    return all[key];
}

long long searchlimit(int start, int end, int depth) {
    if (start == end) {
        return (depth < m) ? 1 : 0;
    }
    tuple<int, int, int> key = make_tuple(start, end, depth);
    if (limit.find(key) != limit.end()) {
        return limit[key];
    }
    limit[key] = 0;
    limit[key] += searchlimit(start + 1, end, depth + 1);
    limit[key] += searchlimit(start, end - 1, depth + 1);
    for (int i = start + 1; i < end; ++i) {
        limit[key] += searchlimit(start, i - 1, depth + 1) * searchlimit(i + 1, end, depth + 1);
    }
    return limit[key];
}

int main() {
    cin >> n >> m;
    long long result = searchall(1, n) - searchlimit(1, n, 1);
    cout << result << endl;
    return 0;
}

